-- Migration: Year 2 - Endocrine Pathology MCQ Bank (PART 6: 236-300)
-- Topics: Metabolic Syndrome, Hyperlipidemias, Advanced MEN/Endo, Hypothalamic Axis
-- Date: 2026-04-24

BEGIN;

DO $$ 
DECLARE 
    v_topic_id UUID;
BEGIN
    -- Ensure Topic exists
    INSERT INTO topics (title, slug, semester_id, year_id, "order")
    VALUES ('Endocrine Pathology', 'endocrine-pathology', 3, 2, 40)
    ON CONFLICT (slug) DO UPDATE SET year_id = 2, semester_id = 3
    RETURNING id INTO v_topic_id;

    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    -- LIPID DISORDERS & METABOLIC SYNDROME (1-10)
    (v_topic_id, '236. A patient presents with eruptive xanthomas, hepatosplenomegaly, and a creamy layer in the supernatant of their blood sample. Diagnosis?', '["Familial Hypercholesterolemia (Type IIa)", "Familial Chylomicronemia (Type I)", "Dysbetalipoproteinemia (Type III)", "Hypertriglyceridemia (Type IV)"]', 1, 'Type I hyperlipoproteinemia is caused by a deficiency in Lipoprotein Lipase (LPL) or ApoC-II, leading to massive chylomicron accumulation.'),
    (v_topic_id, '237. Does Familial Chylomicronemia (Type I) increase the risk for atherosclerosis?', '["Yes, severely", "No, it primarily causes pancreatitis", "Yes, but only in males", "No, it causes biliary cirrhosis"]', 1, 'Chylomicrons are too large to enter the vascular wall to cause atherosclerosis. However, massive triglycerides cause severe acute pancreatitis.'),
    (v_topic_id, '238. Familial Hypercholesterolemia (Type IIa) is most commonly caused by a defect in?', '["Lipoprotein Lipase", "ApoE", "LDL Receptor", "ApoB-100"]', 2, 'A defective or absent LDL receptor prevents LDL clearance from the blood, causing severe premature atherosclerosis and tendon xanthomas.'),
    (v_topic_id, '239. A patient presents with palmar xanthomas and premature atherosclerosis. They have a defect in ApoE. Diagnosis?', '["Type I Hyperlipidemia", "Type IIa Hyperlipidemia", "Type III Dysbetalipoproteinemia", "Type IV Hyperlipidemia"]', 2, 'ApoE is required for chylomicron remnant and VLDL remnant uptake by the liver. Lack of it causes accumulation of remnants (IDL), leading to palmar xanthomas.'),
    (v_topic_id, '240. Type IV Hypertriglyceridemia involves the hepatic overproduction of?', '["Chylomicrons", "VLDL", "LDL", "HDL"]', 1, 'Hepatic overproduction of VLDL leads to high triglycerides, associated with obesity, diabetes, and alcohol use.'),
    (v_topic_id, '241. Metabolic Syndrome is defined by insulin resistance and which other core features?', '["Hypotension and high HDL", "Central obesity, hypertension, hypertriglyceridemia, low HDL", "High LDL and normal waist circumference", "Autoimmune beta-cell destruction"]', 1, 'Metabolic syndrome requires 3 of 5: Waist circumference, High Triglycerides, Low HDL, High BP, and High Fasting Glucose.'),
    (v_topic_id, '242. Acanthosis nigricans is a physical exam marker for?', '["Hyperthyroidism", "Insulin resistance", "Adrenal insufficiency", "Pituitary adenoma"]', 1, 'Hyperinsulinemia stimulates IGF-1 receptors on keratinocytes, causing epidermal hyperplasia and hyperpigmentation (acanthosis nigricans). (Note: can also be a paraneoplastic sign of gastric cancer).'),
    (v_topic_id, '243. What is the primary role of HDL?', '["Transport cholesterol from liver to tissues", "Reverse cholesterol transport (tissues to liver)", "Deliver triglycerides to muscle", "Activate LPL"]', 1, 'HDL extracts cholesterol from peripheral tissues and atherosclerotic plaques and returns it to the liver (via CETP and scavenger receptors).'),
    (v_topic_id, '244. Which apolipoprotein is the primary structural component of HDL and activates LCAT?', '["ApoA-I", "ApoB-100", "ApoB-48", "ApoC-II"]', 0, 'ApoA-I is found on HDL and activates LCAT, which esterifies cholesterol for transport.'),
    (v_topic_id, '245. Which apolipoprotein mediates the secretion of chylomicrons from the intestine?', '["ApoB-100", "ApoB-48", "ApoE", "ApoC-II"]', 1, 'ApoB-48 is required for chylomicron assembly in the enterocyte. ApoB-100 is for VLDL/LDL assembly in the liver.'),

    -- DKA vs HHS & DIABETIC CRISIS (11-20)
    (v_topic_id, '246. In Diabetic Ketoacidosis (DKA), what is the total body potassium status vs serum potassium?', '["Total body K+ high, Serum K+ high", "Total body K+ low, Serum K+ normal or high", "Total body K+ normal, Serum K+ low", "Total body K+ low, Serum K+ low"]', 1, 'Lack of insulin and acidosis shift K+ out of cells into the blood. The high serum K+ is then lost in the urine via osmotic diuresis. Total body K+ is depleted despite hyperkalemia.'),
    (v_topic_id, '247. When treating DKA with insulin, what life-threatening shift must be monitored and prevented?', '["Hypercalcemia", "Severe Hypokalemia", "Hypernatremia", "Hypoglycemia only"]', 1, 'Insulin drives glucose and K+ back INTO cells. Because total body K+ is already low, this shift can cause severe, fatal hypokalemia (arrhythmias). K+ is usually replaced with fluids.'),
    (v_topic_id, '248. The primary ketone body produced in DKA that is NOT detected by standard urine dipstick tests is?', '["Acetoacetate", "Acetone", "Beta-hydroxybutyrate", "Pyruvate"]', 2, 'Dipsticks measure acetoacetate. Beta-hydroxybutyrate is the predominant ketone in DKA and must be measured in the serum.'),
    (v_topic_id, '249. What is the classic finding on physical exam in a patient with DKA?', '["Bradycardia", "Kussmaul respirations and fruity breath odor", "Carpopedal spasm", "Pretibial myxedema"]', 1, 'Kussmaul respirations are deep, rapid breaths to blow off CO2 (compensatory respiratory alkalosis). Acetone causes the fruity breath.'),
    (v_topic_id, '250. Hyperosmolar Hyperglycemic State (HHS) is characterized by a serum osmolality typically greater than?', '["280 mOsm/kg", "295 mOsm/kg", "320 mOsm/kg", "400 mOsm/kg"]', 2, 'HHS features profound dehydration and hyperglycemia (>600 mg/dL), leading to serum osmolality >320 mOsm/kg, causing neurologic symptoms (coma).'),
    (v_topic_id, '251. Which fluid is the initial treatment of choice for both DKA and HHS?', '["0.45% NaCl", "0.9% Normal Saline", "D5W", "Hypertonic 3% Saline"]', 1, 'Aggressive volume resuscitation with 0.9% NS is step 1 to restore perfusion and correct the profound volume deficit.'),
    (v_topic_id, '252. In DKA, the anion gap is?', '["Normal", "Decreased", "Increased", "Variable"]', 2, 'DKA causes a High Anion Gap Metabolic Acidosis (MUDPILES: D = DKA) due to unmeasured ketoacids.'),
    (v_topic_id, '253. Cerebral edema during the treatment of DKA is most commonly caused by?', '["Giving potassium too slowly", "Rapid drop in serum osmolality and glucose", "Insulin toxicity", "Acidosis"]', 1, 'Rapid correction of hyperglycemia causes an abrupt drop in serum osmolality; fluid shifts rapidly into the hyperosmolar brain cells, causing swelling. This is especially dangerous in children.'),
    (v_topic_id, '254. Mucormycosis is a fatal fungal infection classically seen in patients with?', '["Well-controlled Type 2 DM", "Diabetic Ketoacidosis (DKA)", "Hypothyroidism", "Cushing Syndrome"]', 1, 'Rhizopus and Mucor species thrive in acidic, high-glucose, high-ketone environments. They invade blood vessels, causing rhinocerebral necrosis (black eschar on palate/face).'),
    (v_topic_id, '255. Treatment for Mucormycosis involves?', '["Fluconazole", "Amphotericin B and surgical debridement", "Caspofungin", "Penicillin"]', 1, 'It is a surgical emergency requiring aggressive debridement and Amphotericin B.'),

    -- ADVANCED PARANEOPLASTIC & ECTOPIC (21-30)
    (v_topic_id, '256. Cerebral Salt Wasting (CSW) mimics SIADH (hyponatremia). How are they differentiated?', '["CSW has hypernatremia", "CSW patients are hypovolemic; SIADH patients are euvolemic", "CSW has high serum osmolality", "SIADH has high urine output"]', 1, 'In CSW (often after brain injury/subarachnoid hemorrhage), the brain releases BNP, causing massive salt AND water loss (hypovolemia). SIADH is a pure water retention issue (euvolemia).'),
    (v_topic_id, '257. Carcinoid Syndrome causes right-sided heart murmurs. Which specific valve lesions are most common?', '["Tricuspid stenosis and pulmonary regurgitation", "Tricuspid regurgitation and pulmonary stenosis", "Mitral stenosis", "Aortic regurgitation"]', 1, 'Serotonin causes fibrosis of the right-sided valves, leading to Tricuspid Regurgitation (TR) and Pulmonary Stenosis (PS).'),
    (v_topic_id, '258. Why do patients with Carcinoid Syndrome develop Niacin (Vitamin B3) deficiency (Pellagra)?', '["Serotonin degrades Niacin", "Tryptophan is shunted toward Serotonin synthesis instead of Niacin synthesis", "The tumor consumes Niacin", "Diarrhea causes Niacin malabsorption"]', 1, 'Tryptophan is the precursor for both. Massive serotonin production depletes tryptophan, leading to pellagra (Diarrhea, Dermatitis, Dementia).'),
    (v_topic_id, '259. A patient with Small Cell Lung Cancer develops proximal muscle weakness that IMPROVES with repetitive use. Diagnosis?', '["Myasthenia Gravis", "Lambert-Eaton Myasthenic Syndrome", "Polymyositis", "Guillain-Barre"]', 1, 'Lambert-Eaton is a paraneoplastic syndrome where antibodies attack presynaptic voltage-gated Calcium channels. Repetitive stimulation builds up calcium, improving weakness.'),
    (v_topic_id, '260. How does Lambert-Eaton differentiate from Myasthenia Gravis (MG)?', '["MG attacks presynaptic receptors", "MG weakness worsens with use, Lambert-Eaton improves with use", "MG is associated with lung cancer", "Lambert-Eaton has antibodies to the ACh receptor"]', 1, 'MG (post-synaptic ACh receptor antibodies, associated with thymoma) worsens with use. Lambert-Eaton improves with use.'),
    (v_topic_id, '261. Renal Cell Carcinoma can secrete which ectopic hormone, leading to polycythemia?', '["PTHrP", "Erythropoietin (EPO)", "ACTH", "ADH"]', 1, 'RCC frequently secretes EPO, causing a paraneoplastic polycythemia (elevated hematocrit).'),
    (v_topic_id, '262. Squamous cell carcinoma of the lung secretes PTHrP. What does this do to endogenous PTH and 1,25-Vit D levels?', '["High PTH, High Vit D", "Low PTH, Low 1,25-Vit D", "Low PTH, High 1,25-Vit D", "High PTH, Low 1,25-Vit D"]', 1, 'High calcium suppresses endogenous PTH. Since PTH is required to stimulate 1-alpha-hydroxylase, 1,25-Vit D levels will also be low.'),
    (v_topic_id, '263. A patient with a pancreatic mass has severe, refractory hypoglycemia. The tumor is resected, and histology shows amyloid deposition. Diagnosis?', '["Glucagonoma", "Insulinoma", "VIPoma", "Somatostatinoma"]', 1, 'Insulinomas secrete insulin and amylin. The amylin can deposit as amyloid in the tumor.'),
    (v_topic_id, '264. What is the treatment for an inoperable VIPoma?', '["Octreotide", "Insulin", "Glucagon", "Desmopressin"]', 0, 'Octreotide (a somatostatin analog) globally inhibits the release of most GI and pancreatic hormones, effectively controlling WDHA symptoms.'),
    (v_topic_id, '265. Which gastric cell type produces Gastrin?', '["Parietal cells", "Chief cells", "G cells", "D cells"]', 2, 'G cells in the antrum of the stomach (and duodenum) produce gastrin, which stimulates Parietal cells (via ECL cells/histamine) to secrete acid.'),

    -- HYPOTHALAMIC & PITUITARY DEEP DIVE (31-40)
    (v_topic_id, '266. A lesion in the supraoptic nucleus of the hypothalamus will result in?', '["Hypothyroidism", "Diabetes Insipidus", "Addison Disease", "Hyperprolactinemia"]', 1, 'The supraoptic and paraventricular nuclei synthesize ADH and Oxytocin. Damage here causes Central DI.'),
    (v_topic_id, '267. The lateral area of the hypothalamus controls?', '["Satiety", "Hunger", "Cooling", "Heating"]', 1, 'Lateral = Hunger. Destruction leads to anorexia/starvation. (Mnemonic: If you shrink laterally, you need hunger).'),
    (v_topic_id, '268. The ventromedial area of the hypothalamus controls?', '["Satiety", "Hunger", "Cooling", "Heating"]', 0, 'Ventromedial = Satiety. Destruction leads to hyperphagia and massive obesity. (Mnemonic: VentroMedial = Very Massive).'),
    (v_topic_id, '269. The anterior hypothalamus controls?', '["Heating", "Cooling (parasympathetic)", "Hunger", "Satiety"]', 1, 'Anterior = AC (Air Conditioning). It cools the body. Destruction leads to hyperthermia.'),
    (v_topic_id, '270. The posterior hypothalamus controls?', '["Cooling", "Heating (sympathetic)", "Satiety", "Hunger"]', 1, 'Posterior = Heating. It triggers shivering and heat conservation. Destruction leads to poikilothermia (cold blooded).'),
    (v_topic_id, '271. Pro-opiomelanocortin (POMC) is cleaved to produce ACTH, MSH, and which other molecule?', '["Endorphins", "Dopamine", "Oxytocin", "Growth Hormone"]', 0, 'POMC yields ACTH, MSH, and Beta-Endorphins (endogenous opioids).'),
    (v_topic_id, '272. Oxytocin is responsible for?', '["Milk production", "Uterine contractions and milk let-down", "Water retention", "Sodium retention"]', 1, 'Prolactin makes the milk; Oxytocin causes the contraction of myoepithelial cells for milk let-down and uterine smooth muscle for labor.'),
    (v_topic_id, '273. Pituitary adenomas can cause visual defects. A lesion compressing the optic tract (NOT the chiasm) causes?', '["Bitemporal hemianopsia", "Homonymous hemianopsia", "Binasal hemianopsia", "Central scotoma"]', 1, 'While chiasm compression causes bitemporal hemianopsia, lateral extension compressing an optic tract causes contralateral homonymous hemianopsia.'),
    (v_topic_id, '274. Craniopharyngiomas are derived from Rathke pouch. In adults, they are more common than in children. True or False?', '["True", "False", "Equally common", "Only in the elderly"]', 1, 'False. Craniopharyngiomas are the most common suprasellar childhood tumor. They have a bimodal distribution (kids and 50-60s) but are classic in pediatrics.'),
    (v_topic_id, '275. A patient with acromegaly dies of sudden cardiac arrest. What is the most common cause of death in acromegaly?', '["Colon cancer", "Heart failure/Cardiomyopathy", "Pituitary apoplexy", "Airway obstruction"]', 1, 'Cardiomyopathy (hypertrophy leading to heart failure and arrhythmias) is the leading cause of death in acromegaly.'),

    -- COMPREHENSIVE MEN AND GENETICS (41-50)
    (v_topic_id, '276. The MEN1 gene on chromosome 11 codes for which tumor suppressor protein?', '["Retinoblastoma (Rb)", "Menin", "Neurofibromin", "p53"]', 1, 'MEN1 encodes the tumor suppressor protein Menin. Loss of function causes MEN 1 syndrome.'),
    (v_topic_id, '277. Which parathyroid presentation is most common in MEN 1?', '["Single adenoma", "Parathyroid carcinoma", "Asymmetric four-gland hyperplasia", "Agenesis"]', 2, 'Hyperparathyroidism in MEN 1 is almost always due to multi-gland hyperplasia, requiring subtotal parathyroidectomy.'),
    (v_topic_id, '278. The RET proto-oncogene is a?', '["Tumor suppressor", "Receptor Tyrosine Kinase", "G-protein coupled receptor", "Transcription factor"]', 1, 'RET is a Receptor Tyrosine Kinase. Gain-of-function point mutations cause MEN 2A and 2B.'),
    (v_topic_id, '279. Which disease is caused by a LOSS of function mutation in the RET gene?', '["MEN 2A", "MEN 2B", "Hirschsprung Disease", "Neurofibromatosis"]', 2, 'Loss of RET function causes failure of neural crest migration in the colon, leading to aganglionic megacolon (Hirschsprung).'),
    (v_topic_id, '280. A patient has Medullary Thyroid Carcinoma but no family history and no other tumors. What is the likelihood of a RET mutation?', '["0%", "10%", "25%", "100%"]', 2, 'Approximately 25-30% of sporadic (non-MEN) Medullary Thyroid Carcinomas have somatic RET mutations.'),
    (v_topic_id, '281. Familial Medullary Thyroid Carcinoma (FMTC) is considered a variant of which syndrome?', '["MEN 1", "MEN 2A", "MEN 2B", "Autoimmune Polyendocrine Syndrome"]', 1, 'FMTC involves a RET mutation causing only MTC without the pheochromocytoma or parathyroid hyperplasia seen in MEN 2A.'),
    (v_topic_id, '282. Neurofibromatosis Type 1 (NF1) is associated with an increased risk of which endocrine tumor?', '["Insulinoma", "Pheochromocytoma", "Papillary Thyroid Carcinoma", "Prolactinoma"]', 1, 'NF1 (von Recklinghausen disease) is associated with Pheochromocytoma, optic gliomas, and neurofibromas.'),
    (v_topic_id, '283. Von Hippel-Lindau (VHL) disease increases the risk for which tumors?', '["Hemangioblastomas, Renal Cell Carcinoma, Pheochromocytoma", "Pituitary, Parathyroid, Pancreas", "Medullary Thyroid Carcinoma", "Gastrinoma"]', 0, 'VHL is an autosomal dominant tumor suppressor defect causing hemangioblastomas (retina/CNS), bilateral RCC, and pheochromocytoma.'),
    (v_topic_id, '284. Carney Complex is associated with?', '["Cardiac myxomas, skin pigmentation, and endocrine overactivity (Cushing)", "MEN 1 and NF1 overlap", "Hypothyroidism and vitiligo", "Acromegaly alone"]', 0, 'Carney complex involves spotty skin pigmentation, myxomas (heart, skin), and endocrine tumors (primary pigmented nodular adrenocortical disease causing Cushing syndrome).'),
    (v_topic_id, '285. A patient with primary hyperparathyroidism develops a brown jaw mass. Biopsy shows giant cells. Diagnosis?', '["Osteosarcoma", "Ameloblastoma", "Brown tumor of Osteitis Fibrosa Cystica", "Ewing Sarcoma"]', 2, 'Brown tumors are areas of intense bone resorption, hemorrhage, and giant cell accumulation (hemosiderin gives the brown color) caused by severe hyperparathyroidism.'),

    -- FINAL MISCELLANEOUS REVIEW (51-65)
    (v_topic_id, '286. What is the effect of PTH on the proximal convoluted tubule (PCT)?', '["Increases calcium reabsorption", "Increases phosphate reabsorption", "Inhibits Na/PO4 cotransporter (causing phosphaturia)", "Stimulates aldosterone release"]', 2, 'PTH "trashes" phosphate by inhibiting the Na/PO4 cotransporter in the PCT. It reabsorbs Calcium in the Distal Convoluted Tubule (DCT).'),
    (v_topic_id, '287. Hypomagnesemia has what effect on PTH?', '["Stimulates it heavily", "Mild decrease inhibits PTH; severe decrease stimulates it", "Mild decrease stimulates PTH; severe decrease inhibits it", "No effect"]', 2, 'Mild low Mg2+ stimulates PTH. However, SEVERE hypomagnesemia (e.g., in alcoholism or PPI use) paralyzes the parathyroid gland, causing paradoxical low PTH and resulting hypocalcemia.'),
    (v_topic_id, '288. How does an increase in serum pH (Alkalosis) affect ionized calcium levels?', '["Increases ionized calcium", "Decreases ionized calcium", "No effect", "Decreases total body calcium"]', 1, 'In alkalosis, H+ unbinds from albumin. Calcium binds to the newly freed albumin sites, dropping the free (ionized) calcium level and causing symptoms of hypocalcemia (tetany/cramps).'),
    (v_topic_id, '289. How does Vitamin D toxicity present?', '["Hypercalcemia, hyperphosphatemia, and nephrocalcinosis", "Hypocalcemia and rickets", "Hypercalcemia and hypophosphatemia", "Normal Ca/PO4 but severe bone pain"]', 0, 'Excess Vit D (often from granulomatous diseases or overdose) causes massive gut absorption of BOTH Ca2+ and PO4, leading to metastatic calcification in the kidneys (nephrocalcinosis).'),
    (v_topic_id, '290. What is the primary source of 1,25-dihydroxycholecalciferol in a patient with severe sarcoidosis?', '["Kidney", "Liver", "Skin", "Epithelioid Macrophages"]', 3, 'The granuloma macrophages express their own 1-alpha-hydroxylase, independent of PTH control.'),
    (v_topic_id, '291. Which autoantibody is diagnostic for Graves Disease?', '["Anti-TPO", "Anti-Thyroglobulin", "Thyroid Stimulating Immunoglobulin (TSI)", "Anti-TSH Receptor Blocking Antibody"]', 2, 'TSI is an activating antibody against the TSH receptor.'),
    (v_topic_id, '292. Which drug is used to treat the exophthalmos in severe Graves Disease?', '["Methimazole", "Propranolol", "Corticosteroids", "Radioactive Iodine"]', 2, 'Thioamides and beta-blockers do NOT fix the exophthalmos (which is immune-fibroblast mediated). High-dose steroids reduce the retro-orbital inflammation. Radioactive iodine can actually worsen exophthalmos initially.'),
    (v_topic_id, '293. A pregnant woman in her 3rd trimester has hyperthyroidism. Which drug is used?', '["Propylthiouracil (PTU)", "Methimazole", "Radioactive Iodine", "Surgery only"]', 1, 'Methimazole is preferred in the 2nd and 3rd trimesters due to PTU''s severe liver toxicity. PTU is only used in the 1st trimester to avoid Methimazole-induced aplasia cutis.'),
    (v_topic_id, '294. Neonatal thyrotoxicosis is caused by?', '["Maternal TSH crossing the placenta", "Maternal TSI crossing the placenta", "Maternal T4 crossing the placenta", "Fetal autonomy"]', 1, 'IgG antibodies (like TSI in Graves disease) can cross the placenta, causing transient hyperthyroidism in the newborn until the maternal antibodies clear.'),
    (v_topic_id, '295. De Quervain (Subacute) Thyroiditis typically presents with?', '["Painful goiter, high ESR, hyperthyroid phase, following a viral illness", "Painless goiter, normal ESR, hypothyroid", "Woody hard thyroid", "Exophthalmos"]', 0, 'It is a granulomatous inflammation characterized by a very tender neck/thyroid after an upper respiratory infection.'),
    (v_topic_id, '296. Reidel Thyroiditis is characterized by?', '["Lymphocytic infiltrate", "Granulomatous giant cells", "Extensive fibrosis extending to local structures (airway)", "Amyloid stroma"]', 2, 'IgG4-related systemic fibrosis replaces the thyroid and invades the trachea/muscles, creating a painless, fixed, rock-hard mass.'),
    (v_topic_id, '297. Which thyroid cancer spreads via hematogenous routes rather than lymphatics?', '["Papillary", "Follicular", "Medullary", "Anaplastic"]', 1, 'Follicular carcinoma invades blood vessels and spreads hematogenously (to bone and lungs). Papillary spreads via lymphatics (cervical nodes).'),
    (v_topic_id, '298. Orphan Annie eye nuclei and Psammoma bodies = ?', '["Follicular Carcinoma", "Anaplastic Carcinoma", "Papillary Carcinoma", "Medullary Carcinoma"]', 2, 'Classic histological markers for Papillary Thyroid Carcinoma.'),
    (v_topic_id, '299. Amyloid stroma and Calcitonin secretion = ?', '["Medullary Carcinoma", "Follicular Carcinoma", "Papillary Carcinoma", "Anaplastic Carcinoma"]', 0, 'Classic for Medullary Thyroid Carcinoma (C-cell origin).'),
    (v_topic_id, '300. Which finding differentiates a primary adrenal insufficiency (Addison) from a secondary (pituitary) insufficiency?', '["Hyponatremia", "Hyperpigmentation and hyperkalemia", "Hypotension", "Lethargy"]', 1, 'Primary has high ACTH (causing hyperpigmentation via MSH) and lacks aldosterone (causing hyperkalemia). Secondary has low ACTH (no pigmentation) and intact aldosterone (normal potassium).');

    RAISE NOTICE 'SUCCESS: Endocrine Pathology MCQs Part 6 (236-300) registered.';
END $$;

COMMIT;
